window.APP_DATA={"title": "台灣薪資最低的十種職業", "version": "日式動漫卡通・明亮女聲", "voice": "B05-Conan 主角・女聲", "total_seconds": 909.54, "timeline": [{"scene_id": 1, "image_scene_id": 1, "start": 0.0, "end": 3.6, "duration": 3.6, "section": "開場 Hook", "caption_text": "一個月到手不到三萬二，在臺灣，", "motion": "slow-zoom-out"}, {"scene_id": 2, "image_scene_id": 2, "start": 3.6, "end": 6.91, "duration": 3.31, "section": "開場 Hook", "caption_text": "究竟是一份工作的真實行情，", "motion": "pan-left"}, {"scene_id": 3, "image_scene_id": 3, "start": 6.91, "end": 10.65, "duration": 3.74, "section": "開場 Hook", "caption_text": "還是一道被整個社會刻意繞開的警訊？", "motion": "pan-right"}, {"scene_id": 4, "image_scene_id": 4, "start": 10.65, "end": 14.25, "duration": 3.5999999999999996, "section": "開場 Hook", "caption_text": "先別急著把低薪推給年輕人不努力，", "motion": "slow-zoom-in"}, {"scene_id": 5, "image_scene_id": 5, "start": 14.25, "end": 18.35, "duration": 4.100000000000001, "section": "開場 Hook", "caption_text": "當數據一旦攤開，真相遠比不努力更殘酷。", "motion": "slow-zoom-out"}, {"scene_id": 6, "image_scene_id": 6, "start": 18.35, "end": 21.9, "duration": 3.549999999999997, "section": "開場 Hook", "caption_text": "二零二零年開始臺灣的最低工資，", "motion": "pan-left"}, {"scene_id": 7, "image_scene_id": 7, "start": 21.9, "end": 25.67, "duration": 3.770000000000003, "section": "開場 Hook", "caption_text": "已經調高到月薪兩萬九千五百元，", "motion": "pan-right"}, {"scene_id": 8, "image_scene_id": 8, "start": 25.67, "end": 29.25, "duration": 3.5799999999999983, "section": "開場 Hook", "caption_text": "這聽起來一切都在朝對的方向走，", "motion": "slow-zoom-in"}, {"scene_id": 9, "image_scene_id": 9, "start": 29.25, "end": 33.16, "duration": 3.9099999999999966, "section": "開場 Hook", "caption_text": "但把鏡頭拉近會看見另一組扎心數字。", "motion": "slow-zoom-out"}, {"scene_id": 10, "image_scene_id": 10, "start": 33.16, "end": 36.9, "duration": 3.740000000000002, "section": "開場 Hook", "caption_text": "全台受雇員工全年總薪資中位數，", "motion": "pan-left"}, {"scene_id": 11, "image_scene_id": 11, "start": 36.9, "end": 39.73, "duration": 2.8299999999999983, "section": "開場 Hook", "caption_text": "是五十四萬六千元，", "motion": "pan-right"}, {"scene_id": 12, "image_scene_id": 12, "start": 39.73, "end": 43.23, "duration": 3.5, "section": "開場 Hook", "caption_text": "而低薪產業全年總薪資中位數，", "motion": "slow-zoom-in"}, {"scene_id": 13, "image_scene_id": 13, "start": 43.23, "end": 46.09, "duration": 2.8600000000000065, "section": "開場 Hook", "caption_text": "卻只有三十八萬上下。", "motion": "slow-zoom-out"}, {"scene_id": 14, "image_scene_id": 14, "start": 46.09, "end": 49.71, "duration": 3.6199999999999974, "section": "開場 Hook", "caption_text": "這十六萬多的落差不是抽象的統計，", "motion": "pan-left"}, {"scene_id": 15, "image_scene_id": 15, "start": 49.71, "end": 53.21, "duration": 3.5, "section": "開場 Hook", "caption_text": "而是每個月一萬三千多元的差距，", "motion": "pan-right"}, {"scene_id": 16, "image_scene_id": 16, "start": 53.21, "end": 57.1, "duration": 3.8900000000000006, "section": "開場 Hook", "caption_text": "是決定能不能交出房租學費的分水嶺。", "motion": "slow-zoom-in"}, {"scene_id": 17, "image_scene_id": 17, "start": 57.1, "end": 60.17, "duration": 3.0700000000000003, "section": "開場 Hook", "caption_text": "今天就跟著好奇風向標，", "motion": "slow-zoom-out"}, {"scene_id": 18, "image_scene_id": 18, "start": 60.17, "end": 63.77, "duration": 3.6000000000000014, "section": "開場 Hook", "caption_text": "一起看看台灣薪資最低的十種職業。", "motion": "pan-left"}, {"scene_id": 19, "image_scene_id": 19, "start": 63.77, "end": 67.78, "duration": 4.009999999999998, "section": "第10名｜行政助理／一般文書人員", "caption_text": "第十名，行政助理與一般文書人員。", "motion": "pan-right"}, {"scene_id": 20, "image_scene_id": 20, "start": 67.78, "end": 72.12, "duration": 4.340000000000003, "section": "第10名｜行政助理／一般文書人員", "caption_text": "這大概是所有職缺裡最被當成理所當然的。", "motion": "slow-zoom-in"}, {"scene_id": 21, "image_scene_id": 21, "start": 72.12, "end": 76.08, "duration": 3.9599999999999937, "section": "第10名｜行政助理／一般文書人員", "caption_text": "表面上他是坐在辦公室吹冷氣的白領，", "motion": "slow-zoom-out"}, {"scene_id": 22, "image_scene_id": 22, "start": 76.08, "end": 79.15, "duration": 3.0700000000000074, "section": "第10名｜行政助理／一般文書人員", "caption_text": "名片上硬著專員兩個字，", "motion": "pan-left"}, {"scene_id": 23, "image_scene_id": 23, "start": 79.15, "end": 83.4, "duration": 4.25, "section": "第10名｜行政助理／一般文書人員", "caption_text": "實際上他是一間公司裡最安靜也最忙的雜工。", "motion": "pan-right"}, {"scene_id": 24, "image_scene_id": 24, "start": 83.4, "end": 87.22, "duration": 3.819999999999993, "section": "第10名｜行政助理／一般文書人員", "caption_text": "阿的一天從計算機開機那一刻就失控了，", "motion": "slow-zoom-in"}, {"scene_id": 25, "image_scene_id": 25, "start": 87.22, "end": 91.37, "duration": 4.150000000000006, "section": "第10名｜行政助理／一般文書人員", "caption_text": "電話永遠比人先到，一杯水還沒喝完，", "motion": "slow-zoom-out"}, {"scene_id": 26, "image_scene_id": 26, "start": 91.37, "end": 94.49, "duration": 3.1199999999999903, "section": "第10名｜行政助理／一般文書人員", "caption_text": "下一個指令就又壓了下來，", "motion": "pan-left"}, {"scene_id": 27, "image_scene_id": 27, "start": 94.49, "end": 98.74, "duration": 4.25, "section": "第10名｜行政助理／一般文書人員", "caption_text": "收發信件、整理資料、甚至倒水，", "motion": "pan-right"}, {"scene_id": 28, "image_scene_id": 28, "start": 98.74, "end": 103.13, "duration": 4.390000000000001, "section": "第10名｜行政助理／一般文書人員", "caption_text": "還有打掃廁所，最後全落到同一個人頭上。", "motion": "slow-zoom-in"}, {"scene_id": 29, "image_scene_id": 29, "start": 103.13, "end": 106.75, "duration": 3.6200000000000045, "section": "第10名｜行政助理／一般文書人員", "caption_text": "行政助理在中小企業更像一塊磚，", "motion": "slow-zoom-out"}, {"scene_id": 30, "image_scene_id": 30, "start": 106.75, "end": 110.83, "duration": 4.079999999999998, "section": "第10名｜行政助理／一般文書人員", "caption_text": "哪裡缺就往哪裡搬，身兼多重角色，", "motion": "pan-left"}, {"scene_id": 31, "image_scene_id": 31, "start": 110.83, "end": 114.72, "duration": 3.8900000000000006, "section": "第10名｜行政助理／一般文書人員", "caption_text": "替代性極高，也代表隨時可以被替換。", "motion": "pan-right"}, {"scene_id": 32, "image_scene_id": 32, "start": 114.72, "end": 118.73, "duration": 4.010000000000005, "section": "第10名｜行政助理／一般文書人員", "caption_text": "更關鍵的是，行政不屬於賺錢的部門，", "motion": "slow-zoom-in"}, {"scene_id": 33, "image_scene_id": 33, "start": 118.73, "end": 122.93, "duration": 4.200000000000003, "section": "第10名｜行政助理／一般文書人員", "caption_text": "不經手合約，業績表上永遠沒有他的名字，", "motion": "slow-zoom-out"}, {"scene_id": 34, "image_scene_id": 34, "start": 122.93, "end": 127.06, "duration": 4.1299999999999955, "section": "第10名｜行政助理／一般文書人員", "caption_text": "所以薪資表上的數字，永遠靜止不動。", "motion": "pan-left"}, {"scene_id": 35, "image_scene_id": 35, "start": 127.06, "end": 131.21, "duration": 4.150000000000006, "section": "第10名｜行政助理／一般文書人員", "caption_text": "隔壁業務成交一筆獎金可能超過他整個月，", "motion": "pan-right"}, {"scene_id": 36, "image_scene_id": 36, "start": 131.21, "end": 135.05, "duration": 3.8400000000000034, "section": "第10名｜行政助理／一般文書人員", "caption_text": "而行政助理把整間公司的雜事吞下，", "motion": "slow-zoom-in"}, {"scene_id": 37, "image_scene_id": 37, "start": 135.05, "end": 138.58, "duration": 3.530000000000001, "section": "第10名｜行政助理／一般文書人員", "caption_text": "卻連一句辛苦了，都很少換來。", "motion": "slow-zoom-out"}, {"scene_id": 38, "image_scene_id": 38, "start": 138.58, "end": 142.88, "duration": 4.299999999999983, "section": "第10名｜行政助理／一般文書人員", "caption_text": "行政助理排在第十名，不是工作沒價值，", "motion": "pan-left"}, {"scene_id": 39, "image_scene_id": 39, "start": 142.88, "end": 147.01, "duration": 4.1299999999999955, "section": "第10名｜行政助理／一般文書人員", "caption_text": "而是市場太習慣他的存在，習慣到忘了，", "motion": "pan-right"}, {"scene_id": 40, "image_scene_id": 40, "start": 147.01, "end": 151.07, "duration": 4.060000000000002, "section": "第10名｜行政助理／一般文書人員", "caption_text": "整間公司的運轉，其實都靠他一個人在撐。", "motion": "slow-zoom-in"}, {"scene_id": 41, "image_scene_id": 41, "start": 151.07, "end": 154.77, "duration": 3.700000000000017, "section": "第10名｜行政助理／一般文書人員", "caption_text": "你身邊，是不是也有這樣的一個人？", "motion": "slow-zoom-out"}, {"scene_id": 42, "image_scene_id": 42, "start": 154.77, "end": 158.92, "duration": 4.149999999999977, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "第九名，門市人員與賣場銷售人員。", "motion": "pan-left"}, {"scene_id": 43, "image_scene_id": 43, "start": 158.92, "end": 161.94, "duration": 3.0200000000000102, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "他們撐起了整條街的燈火，", "motion": "pan-right"}, {"scene_id": 44, "image_scene_id": 44, "start": 161.94, "end": 165.64, "duration": 3.6999999999999886, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "卻很少被進店的顧客正眼看過一次。", "motion": "slow-zoom-in"}, {"scene_id": 45, "image_scene_id": 45, "start": 165.64, "end": 169.74, "duration": 4.100000000000023, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "很多人以為門市工作就是站在店裡等客人，", "motion": "slow-zoom-out"}, {"scene_id": 46, "image_scene_id": 46, "start": 169.74, "end": 173.96, "duration": 4.219999999999999, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "錯了，真正的一天，從開店前就開始了。", "motion": "pan-left"}, {"scene_id": 47, "image_scene_id": 47, "start": 173.96, "end": 178.09, "duration": 4.1299999999999955, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "補貨搬到腰酸，衣服一件件摺好上架，", "motion": "pan-right"}, {"scene_id": 48, "image_scene_id": 48, "start": 178.09, "end": 182.1, "duration": 4.009999999999991, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "標價錢一張張重貼，還要盤點到半夜，", "motion": "slow-zoom-in"}, {"scene_id": 49, "image_scene_id": 49, "start": 182.1, "end": 186.08, "duration": 3.980000000000018, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "數字對不上，就整層從頭再來一次。", "motion": "slow-zoom-out"}, {"scene_id": 50, "image_scene_id": 50, "start": 186.08, "end": 190.06, "duration": 3.9799999999999898, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "光是站著，就是一種巨大的體力消耗，", "motion": "pan-left"}, {"scene_id": 51, "image_scene_id": 51, "start": 190.06, "end": 194.24, "duration": 4.180000000000007, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "每天站立八到十小時，小腿和膝蓋，", "motion": "pan-right"}, {"scene_id": 52, "image_scene_id": 52, "start": 194.24, "end": 197.79, "duration": 3.549999999999983, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "替這份薪水付出了最慘痛的代價。", "motion": "slow-zoom-in"}, {"scene_id": 53, "image_scene_id": 53, "start": 197.79, "end": 201.82, "duration": 4.030000000000001, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "遇到大檔期進貨量翻倍，搬貨到手軟，", "motion": "slow-zoom-out"}, {"scene_id": 54, "image_scene_id": 54, "start": 201.82, "end": 205.97, "duration": 4.150000000000006, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "連坐下來喘口氣，都成了奢侈的幻想。", "motion": "pan-left"}, {"scene_id": 55, "image_scene_id": 55, "start": 205.97, "end": 209.81, "duration": 3.8400000000000034, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "好不容易熬到打烊，還要截帳清點，", "motion": "pan-right"}, {"scene_id": 56, "image_scene_id": 56, "start": 209.81, "end": 213.65, "duration": 3.8400000000000034, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "底薪很低，剩下的全看業績抽成。", "motion": "slow-zoom-in"}, {"scene_id": 57, "image_scene_id": 57, "start": 213.65, "end": 217.75, "duration": 4.099999999999994, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "問題是商圈人潮會退，電商也會搶單，", "motion": "slow-zoom-out"}, {"scene_id": 58, "image_scene_id": 58, "start": 217.75, "end": 221.9, "duration": 4.150000000000006, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "業績掉，抽成沒了，但人還是要站，", "motion": "pan-left"}, {"scene_id": 59, "image_scene_id": 59, "start": 221.9, "end": 226.32, "duration": 4.4199999999999875, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "抽成說穿了，是把經營風險轉嫁給第一線。", "motion": "pan-right"}, {"scene_id": 60, "image_scene_id": 60, "start": 226.32, "end": 230.71, "duration": 4.390000000000015, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "他們九站、輪班、假日全部都在工作，", "motion": "slow-zoom-in"}, {"scene_id": 61, "image_scene_id": 61, "start": 230.71, "end": 235.01, "duration": 4.299999999999983, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "薪資卻長期卡在比最低工資高一點點的位置。", "motion": "slow-zoom-out"}, {"scene_id": 62, "image_scene_id": 62, "start": 235.01, "end": 238.87, "duration": 3.8600000000000136, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "當你下次逛街覺得這家店服務很好的時候，", "motion": "pan-left"}, {"scene_id": 63, "image_scene_id": 63, "start": 238.87, "end": 243.17, "duration": 4.299999999999983, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "有沒有想過，那個人是站了整整八個小時，", "motion": "pan-right"}, {"scene_id": 64, "image_scene_id": 64, "start": 243.17, "end": 245.95, "duration": 2.780000000000001, "section": "第9名｜門市人員／賣場銷售人員", "caption_text": "才換來你這一秒的滿意？", "motion": "slow-zoom-in"}, {"scene_id": 65, "image_scene_id": 65, "start": 245.95, "end": 249.14, "duration": 3.1899999999999977, "section": "第8名｜電話客服人員", "caption_text": "第八名，電話客服人員。", "motion": "slow-zoom-out"}, {"scene_id": 66, "image_scene_id": 66, "start": 249.14, "end": 253.34, "duration": 4.200000000000017, "section": "第8名｜電話客服人員", "caption_text": "這是一份看不見臉，卻要逼自己笑的工作。", "motion": "pan-left"}, {"scene_id": 67, "image_scene_id": 67, "start": 253.34, "end": 257.56, "duration": 4.219999999999999, "section": "第8名｜電話客服人員", "caption_text": "耳機戴上，八個小時裡耳邊只有負面情緒，", "motion": "pan-right"}, {"scene_id": 68, "image_scene_id": 68, "start": 257.56, "end": 262.31, "duration": 4.75, "section": "第8名｜電話客服人員", "caption_text": "催貨的、退款的、乃至純粹找人出氣的，", "motion": "slow-zoom-in"}, {"scene_id": 69, "image_scene_id": 69, "start": 262.31, "end": 266.44, "duration": 4.1299999999999955, "section": "第8名｜電話客服人員", "caption_text": "電話一接起來，第一句話往往是指責。", "motion": "slow-zoom-out"}, {"scene_id": 70, "image_scene_id": 70, "start": 266.44, "end": 270.95, "duration": 4.509999999999991, "section": "第8名｜電話客服人員", "caption_text": "客服人員必須在標準流程裡，把委屈吞下去，", "motion": "pan-left"}, {"scene_id": 71, "image_scene_id": 71, "start": 270.95, "end": 275.39, "duration": 4.439999999999998, "section": "第8名｜電話客服人員", "caption_text": "不能頂嘴、不能掛斷、不能顯露任何不滿，", "motion": "pan-right"}, {"scene_id": 72, "image_scene_id": 72, "start": 275.39, "end": 279.42, "duration": 4.03000000000003, "section": "第8名｜電話客服人員", "caption_text": "因為每一通電話都有錄音，每句都有評分。", "motion": "slow-zoom-in"}, {"scene_id": 73, "image_scene_id": 73, "start": 279.42, "end": 283.98, "duration": 4.560000000000002, "section": "第8名｜電話客服人員", "caption_text": "下了班才發現，自己一直在演情緒穩定的人，", "motion": "slow-zoom-out"}, {"scene_id": 74, "image_scene_id": 74, "start": 283.98, "end": 288.3, "duration": 4.319999999999993, "section": "第8名｜電話客服人員", "caption_text": "時間久了，連自己真正的情緒都分不清楚了。", "motion": "pan-left"}, {"scene_id": 75, "image_scene_id": 75, "start": 288.3, "end": 290.965, "duration": 2.6649999999999636, "section": "第8名｜電話客服人員", "caption_text": "為什麽這麽累薪水卻低？因為企業視為成本，", "motion": "pan-right"}, {"scene_id": 75, "image_scene_id": 76, "start": 290.965, "end": 293.63, "duration": 2.6650000000000205, "section": "第8名｜電話客服人員", "caption_text": "為什麽這麽累薪水卻低？因為企業視為成本，", "motion": "slow-zoom-in"}, {"scene_id": 76, "image_scene_id": 77, "start": 293.63, "end": 297.97, "duration": 4.340000000000032, "section": "第8名｜電話客服人員", "caption_text": "做得好是應該，但只要一通投訴就前功盡棄。", "motion": "slow-zoom-out"}, {"scene_id": 77, "image_scene_id": 78, "start": 297.97, "end": 301.4, "duration": 3.42999999999995, "section": "第8名｜電話客服人員", "caption_text": "底薪往往就落在最低工資附近，", "motion": "pan-left"}, {"scene_id": 78, "image_scene_id": 79, "start": 301.4, "end": 305.94, "duration": 4.5400000000000205, "section": "第8名｜電話客服人員", "caption_text": "那些加班費加一家，才勉強看起來像份薪水。", "motion": "pan-right"}, {"scene_id": 79, "image_scene_id": 80, "start": 305.94, "end": 310.62, "duration": 4.680000000000007, "section": "第8名｜電話客服人員", "caption_text": "情緒勞動，是這份工作最累也最隱形的成本。", "motion": "slow-zoom-in"}, {"scene_id": 80, "image_scene_id": 81, "start": 310.62, "end": 314.46, "duration": 3.839999999999975, "section": "第8名｜電話客服人員", "caption_text": "電話客服守護了品牌最後的一道門面，", "motion": "slow-zoom-out"}, {"scene_id": 81, "image_scene_id": 82, "start": 314.46, "end": 318.76, "duration": 4.300000000000011, "section": "第8名｜電話客服人員", "caption_text": "卻很少有人回頭問一句，那個人過得好不好？", "motion": "pan-left"}, {"scene_id": 82, "image_scene_id": 83, "start": 318.76, "end": 322.94, "duration": 4.180000000000007, "section": "第8名｜電話客服人員", "caption_text": "下一次你想對客服發脾氣時，請記得，", "motion": "pan-right"}, {"scene_id": 83, "image_scene_id": 84, "start": 322.94, "end": 326.83, "duration": 3.8899999999999864, "section": "第8名｜電話客服人員", "caption_text": "電話那一頭也是同樣在為生活努力的人。", "motion": "slow-zoom-in"}, {"scene_id": 84, "image_scene_id": 85, "start": 326.83, "end": 330.84, "duration": 4.009999999999991, "section": "第7名｜安親班老師／補習班助教", "caption_text": "第七名，安親班老師與補習班助教。", "motion": "slow-zoom-out"}, {"scene_id": 85, "image_scene_id": 86, "start": 330.84, "end": 335.42, "duration": 4.580000000000041, "section": "第7名｜安親班老師／補習班助教", "caption_text": "聽到教育兩個字，腦海裡浮現的是講台光環，", "motion": "pan-left"}, {"scene_id": 86, "image_scene_id": 87, "start": 335.42, "end": 340.1, "duration": 4.680000000000007, "section": "第7名｜安親班老師／補習班助教", "caption_text": "但真正撐起補教產業的，卻是那些光照不到的人。", "motion": "pan-right"}, {"scene_id": 87, "image_scene_id": 88, "start": 340.1, "end": 344.16, "duration": 4.060000000000002, "section": "第7名｜安親班老師／補習班助教", "caption_text": "安親班老師的一天，從放學的鐘聲開始，", "motion": "slow-zoom-in"}, {"scene_id": 88, "image_scene_id": 89, "start": 344.16, "end": 348.02, "duration": 3.859999999999957, "section": "第7名｜安親班老師／補習班助教", "caption_text": "要站在校門口接孩子，一個都不能少。", "motion": "slow-zoom-out"}, {"scene_id": 89, "image_scene_id": 90, "start": 348.02, "end": 350.54, "duration": 2.5200000000000387, "section": "第7名｜安親班老師／補習班助教", "caption_text": "回到教室，改作業、盯功課、複習進度，", "motion": "pan-left"}, {"scene_id": 89, "image_scene_id": 91, "start": 350.54, "end": 353.06, "duration": 2.519999999999982, "section": "第7名｜安親班老師／補習班助教", "caption_text": "回到教室，改作業、盯功課、複習進度，", "motion": "pan-right"}, {"scene_id": 90, "image_scene_id": 92, "start": 353.06, "end": 357.33, "duration": 4.269999999999982, "section": "第7名｜安親班老師／補習班助教", "caption_text": "聯絡簿一本本回，家長的訊息深夜還在響，", "motion": "slow-zoom-in"}, {"scene_id": 91, "image_scene_id": 93, "start": 357.33, "end": 360.59, "duration": 3.259999999999991, "section": "第7名｜安親班老師／補習班助教", "caption_text": "字裡行間全都是焦慮和責怪。", "motion": "slow-zoom-out"}, {"scene_id": 92, "image_scene_id": 94, "start": 360.59, "end": 364.53, "duration": 3.9399999999999977, "section": "第7名｜安親班老師／補習班助教", "caption_text": "孩子跌倒要處理，孩子吵架要排解，", "motion": "pan-left"}, {"scene_id": 93, "image_scene_id": 95, "start": 364.53, "end": 368.44, "duration": 3.910000000000025, "section": "第7名｜安親班老師／補習班助教", "caption_text": "考砸了，第一個被追著問的還是老師。", "motion": "pan-right"}, {"scene_id": 94, "image_scene_id": 96, "start": 368.44, "end": 373.07, "duration": 4.6299999999999955, "section": "第7名｜安親班老師／補習班助教", "caption_text": "這份工作有個殘酷特質：責任大得像養孩子，", "motion": "slow-zoom-in"}, {"scene_id": 95, "image_scene_id": 97, "start": 373.07, "end": 376.26, "duration": 3.1899999999999977, "section": "第7名｜安親班老師／補習班助教", "caption_text": "回報卻小得像在領零用錢。", "motion": "slow-zoom-out"}, {"scene_id": 96, "image_scene_id": 98, "start": 376.26, "end": 380.41, "duration": 4.150000000000034, "section": "第7名｜安親班老師／補習班助教", "caption_text": "一個老師要同時面對十幾個學生和家庭，", "motion": "pan-left"}, {"scene_id": 97, "image_scene_id": 99, "start": 380.41, "end": 384.63, "duration": 4.21999999999997, "section": "第7名｜安親班老師／補習班助教", "caption_text": "稍有疏忽，就是隔天家長一早的投訴電話。", "motion": "pan-right"}, {"scene_id": 98, "image_scene_id": 100, "start": 384.63, "end": 389.29, "duration": 4.660000000000025, "section": "第7名｜安親班老師／補習班助教", "caption_text": "責任全天候掛身上，薪水卻沒跟著責任算。", "motion": "slow-zoom-in"}, {"scene_id": 99, "image_scene_id": 101, "start": 389.29, "end": 393.73, "duration": 4.439999999999998, "section": "第7名｜安親班老師／補習班助教", "caption_text": "市場競爭激烈，小型補習班為了活下去，", "motion": "slow-zoom-out"}, {"scene_id": 100, "image_scene_id": 102, "start": 393.73, "end": 398.07, "duration": 4.339999999999975, "section": "第7名｜安親班老師／補習班助教", "caption_text": "基層助教和課照老師就成了最先被壓縮的。", "motion": "pan-left"}, {"scene_id": 101, "image_scene_id": 103, "start": 398.07, "end": 402.32, "duration": 4.25, "section": "第7名｜安親班老師／補習班助教", "caption_text": "改不完的作業，加上招生季還要發傳單，", "motion": "pan-right"}, {"scene_id": 102, "image_scene_id": 104, "start": 402.32, "end": 406.86, "duration": 4.5400000000000205, "section": "第7名｜安親班老師／補習班助教", "caption_text": "明星名師一堂課的收入，可能超過他一整月。", "motion": "slow-zoom-in"}, {"scene_id": 103, "image_scene_id": 105, "start": 406.86, "end": 411.25, "duration": 4.389999999999986, "section": "第7名｜安親班老師／補習班助教", "caption_text": "他們用愛心撐起孩子，卻換不來體面的未來。", "motion": "slow-zoom-out"}, {"scene_id": 104, "image_scene_id": 106, "start": 411.25, "end": 414.73, "duration": 3.480000000000018, "section": "第7名｜安親班老師／補習班助教", "caption_text": "這份工作，抗著別人的未來，", "motion": "pan-left"}, {"scene_id": 105, "image_scene_id": 107, "start": 414.73, "end": 417.47, "duration": 2.740000000000009, "section": "第7名｜安親班老師／補習班助教", "caption_text": "卻養不起自己的現在。", "motion": "pan-right"}, {"scene_id": 106, "image_scene_id": 108, "start": 417.47, "end": 421.55, "duration": 4.079999999999984, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "第六名，清潔人員與環境整理人員。", "motion": "slow-zoom-in"}, {"scene_id": 107, "image_scene_id": 109, "start": 421.55, "end": 425.53, "duration": 3.9799999999999613, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "凌晨四點，大多數人還在溫暖的夢鄉，", "motion": "slow-zoom-out"}, {"scene_id": 108, "image_scene_id": 110, "start": 425.53, "end": 429.95, "duration": 4.420000000000016, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "清潔人員已經穿上反光背心，開始工作。", "motion": "pan-left"}, {"scene_id": 109, "image_scene_id": 111, "start": 429.95, "end": 434.22, "duration": 4.270000000000039, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "他們是城市裡最早上班卻最不被看見的一群。", "motion": "pan-right"}, {"scene_id": 110, "image_scene_id": 112, "start": 434.22, "end": 438.73, "duration": 4.509999999999991, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "辦公室垃圾桶、醫院消毒水、捷運月台，", "motion": "slow-zoom-in"}, {"scene_id": 111, "image_scene_id": 113, "start": 438.73, "end": 443.19, "duration": 4.4599999999999795, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "每一處乾淨背後，都站著一雙磨出老繭的手。", "motion": "slow-zoom-out"}, {"scene_id": 112, "image_scene_id": 114, "start": 443.19, "end": 447.61, "duration": 4.420000000000016, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "他們在人群醒來前工作，在散去之後收尾，", "motion": "pan-left"}, {"scene_id": 113, "image_scene_id": 115, "start": 447.61, "end": 452.03, "duration": 4.419999999999959, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "永遠站在最不起眼的角落，做不能中斷的事。", "motion": "pan-right"}, {"scene_id": 114, "image_scene_id": 116, "start": 452.03, "end": 456.37, "duration": 4.340000000000032, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "只要停工一天，整棟大樓就會陷入癱瘓惡臭。", "motion": "slow-zoom-in"}, {"scene_id": 115, "image_scene_id": 117, "start": 456.37, "end": 460.21, "duration": 3.839999999999975, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "這份工作的專業，長期被嚴重低估，", "motion": "slow-zoom-out"}, {"scene_id": 116, "image_scene_id": 118, "start": 460.21, "end": 465.03, "duration": 4.819999999999993, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "醫院感控消毒、無塵室落塵控制，都需技術。", "motion": "pan-left"}, {"scene_id": 117, "image_scene_id": 119, "start": 465.03, "end": 469.21, "duration": 4.180000000000007, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "但這份專業，卻從來沒有反映在薪水上。", "motion": "pan-right"}, {"scene_id": 118, "image_scene_id": 120, "start": 469.21, "end": 473.99, "duration": 4.78000000000003, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "更關鍵的是外包制度橫行，中間商層層剝水，", "motion": "slow-zoom-in"}, {"scene_id": 119, "image_scene_id": 121, "start": 473.99, "end": 478.5, "duration": 4.509999999999991, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "最後進到口袋的薪水，已經被壓得所剩無幾。", "motion": "slow-zoom-out"}, {"scene_id": 120, "image_scene_id": 122, "start": 478.5, "end": 482.96, "duration": 4.4599999999999795, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "用最耗體力的方式，換來最接近最低的數字。", "motion": "pan-left"}, {"scene_id": 121, "image_scene_id": 123, "start": 482.96, "end": 487.66, "duration": 4.7000000000000455, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "做了十幾年清潔，薪水也只勉強跟著低薪調。", "motion": "pan-right"}, {"scene_id": 122, "image_scene_id": 124, "start": 487.66, "end": 492.08, "duration": 4.419999999999959, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "我們習慣了乾淨，卻習慣忽視擦地板的背影。", "motion": "slow-zoom-in"}, {"scene_id": 123, "image_scene_id": 125, "start": 492.08, "end": 496.42, "duration": 4.340000000000032, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "下次再看見彎著腰的人，請給予應有的尊重，", "motion": "slow-zoom-out"}, {"scene_id": 124, "image_scene_id": 126, "start": 496.42, "end": 500.07, "duration": 3.6499999999999773, "section": "第6名｜清潔人員／環境整理人員", "caption_text": "那個背影，值得被整個社會看見。", "motion": "pan-left"}, {"scene_id": 125, "image_scene_id": 127, "start": 500.07, "end": 503.62, "duration": 3.5500000000000114, "section": "第5名｜餐飲外場服務人員", "caption_text": "第五名，餐飲外場服務人員。", "motion": "pan-right"}, {"scene_id": 126, "image_scene_id": 128, "start": 503.62, "end": 507.84, "duration": 4.21999999999997, "section": "第5名｜餐飲外場服務人員", "caption_text": "餐廳的尖峰時段，是一場沒有硝煙的戰爭。", "motion": "slow-zoom-in"}, {"scene_id": 127, "image_scene_id": 129, "start": 507.84, "end": 512.11, "duration": 4.270000000000039, "section": "第5名｜餐飲外場服務人員", "caption_text": "中午十二點到一點，點單像雪片一樣飛來，", "motion": "slow-zoom-out"}, {"scene_id": 128, "image_scene_id": 130, "start": 512.11, "end": 516.55, "duration": 4.439999999999941, "section": "第5名｜餐飲外場服務人員", "caption_text": "外場人員一手端著托盤，腦子裡默默記桌號，", "motion": "pan-left"}, {"scene_id": 129, "image_scene_id": 131, "start": 516.55, "end": 521.13, "duration": 4.580000000000041, "section": "第5名｜餐飲外場服務人員", "caption_text": "腳下幾乎是跑步的節奏，送餐收桌補餐具，", "motion": "pan-right"}, {"scene_id": 130, "image_scene_id": 132, "start": 521.13, "end": 525.38, "duration": 4.25, "section": "第5名｜餐飲外場服務人員", "caption_text": "还要應付催菜的客人，安撫暴躁的情緒。", "motion": "slow-zoom-in"}, {"scene_id": 131, "image_scene_id": 133, "start": 525.38, "end": 530.11, "duration": 4.730000000000018, "section": "第5名｜餐飲外場服務人員", "caption_text": "汗水是工作最固定的配件，水擺在角落放涼，", "motion": "slow-zoom-out"}, {"scene_id": 132, "image_scene_id": 134, "start": 530.11, "end": 533.83, "duration": 3.7200000000000273, "section": "第5名｜餐飲外場服務人員", "caption_text": "常常找不到一個空檔，喝上一口。", "motion": "pan-left"}, {"scene_id": 133, "image_scene_id": 135, "start": 533.83, "end": 538.17, "duration": 4.339999999999918, "section": "第5名｜餐飲外場服務人員", "caption_text": "下班的時候小腿腫了一圈，腳痛得像踩針尖。", "motion": "pan-right"}, {"scene_id": 134, "image_scene_id": 136, "start": 538.17, "end": 542.35, "duration": 4.180000000000064, "section": "第5名｜餐飲外場服務人員", "caption_text": "用餐時段一過，還要擦桌拖地恢復戰場，", "motion": "slow-zoom-in"}, {"scene_id": 135, "image_scene_id": 137, "start": 542.35, "end": 546.72, "duration": 4.3700000000000045, "section": "第5名｜餐飲外場服務人員", "caption_text": "而這一切，換來的薪水卻少得令人心寒。", "motion": "slow-zoom-out"}, {"scene_id": 136, "image_scene_id": 138, "start": 546.72, "end": 550.99, "duration": 4.269999999999982, "section": "第5名｜餐飲外場服務人員", "caption_text": "基層餐飲的薪水，很多還是用時薪計算，", "motion": "pan-left"}, {"scene_id": 137, "image_scene_id": 139, "start": 550.99, "end": 555.38, "duration": 4.389999999999986, "section": "第5名｜餐飲外場服務人員", "caption_text": "一旦排班時數被砍，實領甚至養不起自己。", "motion": "pan-right"}, {"scene_id": 138, "image_scene_id": 140, "start": 555.38, "end": 559.72, "duration": 4.340000000000032, "section": "第5名｜餐飲外場服務人員", "caption_text": "年年喊缺工，卻不願意把薪水真正往上提升，", "motion": "slow-zoom-in"}, {"scene_id": 139, "image_scene_id": 141, "start": 559.72, "end": 563.75, "duration": 4.029999999999973, "section": "第5名｜餐飲外場服務人員", "caption_text": "這是台灣服務業常年累積下來的結構困境。", "motion": "slow-zoom-out"}, {"scene_id": 140, "image_scene_id": 142, "start": 563.75, "end": 568.19, "duration": 4.440000000000055, "section": "第5名｜餐飲外場服務人員", "caption_text": "送上的每道菜都燙手，卻燙不出像樣的薪水；", "motion": "pan-left"}, {"scene_id": 141, "image_scene_id": 143, "start": 568.19, "end": 571.81, "duration": 3.619999999999891, "section": "第5名｜餐飲外場服務人員", "caption_text": "每分鐘的勞動都算得清清楚楚，", "motion": "pan-right"}, {"scene_id": 142, "image_scene_id": 144, "start": 571.81, "end": 575.1, "duration": 3.2900000000000773, "section": "第5名｜餐飲外場服務人員", "caption_text": "卻唯獨算不出一個像樣的未來。", "motion": "slow-zoom-in"}, {"scene_id": 143, "image_scene_id": 145, "start": 575.1, "end": 578.29, "duration": 3.189999999999941, "section": "第4名｜住宿房務人員", "caption_text": "第四名，住宿房務人員。", "motion": "slow-zoom-out"}, {"scene_id": 144, "image_scene_id": 146, "start": 578.29, "end": 581.94, "duration": 3.650000000000091, "section": "第4名｜住宿房務人員", "caption_text": "在飯店裡，最體面的永遠是大廳，", "motion": "pan-left"}, {"scene_id": 145, "image_scene_id": 147, "start": 581.94, "end": 584.8, "duration": 2.8599999999999, "section": "第4名｜住宿房務人員", "caption_text": "最血汗的永遠是後場。", "motion": "pan-right"}, {"scene_id": 146, "image_scene_id": 148, "start": 584.8, "end": 589.19, "duration": 4.3900000000001, "section": "第4名｜住宿房務人員", "caption_text": "退房的客人一走，房務就要開始和時間賽跑，", "motion": "slow-zoom-in"}, {"scene_id": 147, "image_scene_id": 149, "start": 589.19, "end": 593.73, "duration": 4.539999999999964, "section": "第4名｜住宿房務人員", "caption_text": "一間房十幾分鐘，床單要抖平，浴室要擦乾，", "motion": "slow-zoom-out"}, {"scene_id": 148, "image_scene_id": 150, "start": 593.73, "end": 598.17, "duration": 4.439999999999941, "section": "第4名｜住宿房務人員", "caption_text": "每一個細節，都會被下一位客人的眼睛放大。", "motion": "pan-left"}, {"scene_id": 149, "image_scene_id": 151, "start": 598.17, "end": 600.88, "duration": 2.7100000000000364, "section": "第4名｜住宿房務人員", "caption_text": "彎腰、蹲下、抬手，同樣動作一天重複上百次，", "motion": "pan-right"}, {"scene_id": 149, "image_scene_id": 152, "start": 600.88, "end": 603.59, "duration": 2.7100000000000364, "section": "第4名｜住宿房務人員", "caption_text": "彎腰、蹲下、抬手，同樣動作一天重複上百次，", "motion": "slow-zoom-in"}, {"scene_id": 150, "image_scene_id": 153, "start": 603.59, "end": 607.93, "duration": 4.339999999999918, "section": "第4名｜住宿房務人員", "caption_text": "腰背和手腕，是這份工作最早暴廢的部位。", "motion": "slow-zoom-out"}, {"scene_id": 151, "image_scene_id": 154, "start": 607.93, "end": 612.25, "duration": 4.32000000000005, "section": "第4名｜住宿房務人員", "caption_text": "遇到狂歡後的混亂房間，工作量直接翻倍，", "motion": "pan-left"}, {"scene_id": 152, "image_scene_id": 155, "start": 612.25, "end": 615.73, "duration": 3.480000000000018, "section": "第4名｜住宿房務人員", "caption_text": "但薪水，絕對不會跟著翻倍。", "motion": "pan-right"}, {"scene_id": 153, "image_scene_id": 156, "start": 615.73, "end": 619.02, "duration": 3.2899999999999636, "section": "第4名｜住宿房務人員", "caption_text": "旅客享受一晚數千元的房間，", "motion": "slow-zoom-in"}, {"scene_id": 154, "image_scene_id": 157, "start": 619.02, "end": 623.22, "duration": 4.2000000000000455, "section": "第4名｜住宿房務人員", "caption_text": "房務領的，卻是一間房不到百元的清潔費。", "motion": "slow-zoom-out"}, {"scene_id": 155, "image_scene_id": 158, "start": 623.22, "end": 627.92, "duration": 4.699999999999932, "section": "第4名｜住宿房務人員", "caption_text": "營運成本高，人力又常外包，薪水常年被壓死。", "motion": "pan-left"}, {"scene_id": 156, "image_scene_id": 159, "start": 627.92, "end": 631.81, "duration": 3.8899999999999864, "section": "第4名｜住宿房務人員", "caption_text": "他們用最快的速度替別人鋪好乾淨的床，", "motion": "pan-right"}, {"scene_id": 157, "image_scene_id": 160, "start": 631.81, "end": 635.19, "duration": 3.380000000000109, "section": "第4名｜住宿房務人員", "caption_text": "卻鋪不出自己一張穩定的薪水單。", "motion": "slow-zoom-in"}, {"scene_id": 158, "image_scene_id": 161, "start": 635.19, "end": 638.36, "duration": 3.169999999999959, "section": "第3名｜美容美髮助理", "caption_text": "第三名，美容美髮助理。", "motion": "slow-zoom-out"}, {"scene_id": 159, "image_scene_id": 162, "start": 638.36, "end": 641.82, "duration": 3.4600000000000364, "section": "第3名｜美容美髮助理", "caption_text": "這是年輕人踏進服務業的第一站，", "motion": "pan-left"}, {"scene_id": 160, "image_scene_id": 163, "start": 641.82, "end": 645.44, "duration": 3.6200000000000045, "section": "第3名｜美容美髮助理", "caption_text": "也是用夢想換薪水最典型的一站。", "motion": "pan-right"}, {"scene_id": 161, "image_scene_id": 164, "start": 645.44, "end": 647.97, "duration": 2.5299999999999727, "section": "第3名｜美容美髮助理", "caption_text": "洗頭、沖水、收拾染膏藥水、清掃碎髮，", "motion": "slow-zoom-in"}, {"scene_id": 161, "image_scene_id": 165, "start": 647.97, "end": 650.5, "duration": 2.5299999999999727, "section": "第3名｜美容美髮助理", "caption_text": "洗頭、沖水、收拾染膏藥水、清掃碎髮，", "motion": "slow-zoom-out"}, {"scene_id": 162, "image_scene_id": 166, "start": 650.5, "end": 655.11, "duration": 4.610000000000014, "section": "第3名｜美容美髮助理", "caption_text": "手泡在洗髮精裡一整天，指縫乾裂直接脫皮，", "motion": "pan-left"}, {"scene_id": 163, "image_scene_id": 167, "start": 655.11, "end": 658.49, "duration": 3.3799999999999955, "section": "第3名｜美容美髮助理", "caption_text": "這是刻在每一雙手上的職業傷害。", "motion": "pan-right"}, {"scene_id": 164, "image_scene_id": 168, "start": 658.49, "end": 662.79, "duration": 4.2999999999999545, "section": "第3名｜美容美髮助理", "caption_text": "最殘酷的是學徒兩個字，掛上學徒名義，", "motion": "slow-zoom-in"}, {"scene_id": 165, "image_scene_id": 169, "start": 662.79, "end": 665.93, "duration": 3.1399999999999864, "section": "第3名｜美容美髮助理", "caption_text": "薪水就被理所當然地壓低，", "motion": "slow-zoom-out"}, {"scene_id": 166, "image_scene_id": 170, "start": 665.93, "end": 670.71, "duration": 4.780000000000086, "section": "第3名｜美容美髮助理", "caption_text": "要學技術，還得靠下班後的無酬時間自己練習。", "motion": "pan-left"}, {"scene_id": 167, "image_scene_id": 171, "start": 670.71, "end": 675.29, "duration": 4.579999999999927, "section": "第3名｜美容美髮助理", "caption_text": "行業收入兩個極端，熬出頭的設計師越入十萬，", "motion": "pan-right"}, {"scene_id": 168, "image_scene_id": 172, "start": 675.29, "end": 679.63, "duration": 4.340000000000032, "section": "第3名｜美容美髮助理", "caption_text": "但助理全年總薪資中位數卻只有三十八萬一千，", "motion": "slow-zoom-in"}, {"scene_id": 169, "image_scene_id": 173, "start": 679.63, "end": 683.97, "duration": 4.340000000000032, "section": "第3名｜美容美髮助理", "caption_text": "很多人在助理階段，就被低薪磨掉了熱情。", "motion": "slow-zoom-out"}, {"scene_id": 170, "image_scene_id": 174, "start": 683.97, "end": 687.28, "duration": 3.3099999999999454, "section": "第3名｜美容美髮助理", "caption_text": "設計師在鏡子前收穫掌聲，", "motion": "pan-left"}, {"scene_id": 171, "image_scene_id": 175, "start": 687.28, "end": 691.65, "duration": 4.3700000000000045, "section": "第3名｜美容美髮助理", "caption_text": "助理只能整天泡在水裡，換來薄薄的薪水單。", "motion": "pan-right"}, {"scene_id": 172, "image_scene_id": 176, "start": 691.65, "end": 695.87, "duration": 4.220000000000027, "section": "第3名｜美容美髮助理", "caption_text": "通往未來的路，要人用漫長的青春去墊底，", "motion": "slow-zoom-in"}, {"scene_id": 173, "image_scene_id": 177, "start": 695.87, "end": 700.26, "duration": 4.389999999999986, "section": "第3名｜美容美髮助理", "caption_text": "而這份墊底的青春，很多人根本熬不到出頭。", "motion": "slow-zoom-out"}, {"scene_id": 174, "image_scene_id": 178, "start": 700.26, "end": 704.05, "duration": 3.7899999999999636, "section": "第2名｜兼職工讀生／打工族", "caption_text": "第二名，兼職工讀生與打工族。", "motion": "pan-left"}, {"scene_id": 175, "image_scene_id": 179, "start": 704.05, "end": 708.63, "duration": 4.580000000000041, "section": "第2名｜兼職工讀生／打工族", "caption_text": "嚴格來說這不是一個職業，而是一種集體處境。", "motion": "pan-right"}, {"scene_id": 176, "image_scene_id": 180, "start": 708.63, "end": 713.48, "duration": 4.850000000000023, "section": "第2名｜兼職工讀生／打工族", "caption_text": "最低時薪調高到一百九十六元，看起來在進步，", "motion": "slow-zoom-in"}, {"scene_id": 177, "image_scene_id": 181, "start": 713.48, "end": 717.94, "duration": 4.460000000000036, "section": "第2名｜兼職工讀生／打工族", "caption_text": "但真正綁住打工族的，從來不是時薪這兩個字，", "motion": "slow-zoom-out"}, {"scene_id": 178, "image_scene_id": 182, "start": 717.94, "end": 720.58, "duration": 2.6399999999999864, "section": "第2名｜兼職工讀生／打工族", "caption_text": "而是排班這一張紙。", "motion": "pan-left"}, {"scene_id": 179, "image_scene_id": 183, "start": 720.58, "end": 724.64, "duration": 4.059999999999945, "section": "第2名｜兼職工讀生／打工族", "caption_text": "老闆為了控制成本，班表永遠在浮動，", "motion": "pan-right"}, {"scene_id": 180, "image_scene_id": 184, "start": 724.64, "end": 729.01, "duration": 4.3700000000000045, "section": "第2名｜兼職工讀生／打工族", "caption_text": "這週排二十小時，下週可能只剩八小時。", "motion": "slow-zoom-in"}, {"scene_id": 181, "image_scene_id": 185, "start": 729.01, "end": 733.62, "duration": 4.610000000000014, "section": "第2名｜兼職工讀生／打工族", "caption_text": "多排一班是運氣，少排一班就是房租的缺口。", "motion": "slow-zoom-out"}, {"scene_id": 182, "image_scene_id": 186, "start": 733.62, "end": 736.26, "duration": 2.6399999999999864, "section": "第2名｜兼職工讀生／打工族", "caption_text": "時薪再高，乘上不穩定的工時，總收入也搖搖欲墜。", "motion": "pan-left"}, {"scene_id": 182, "image_scene_id": 187, "start": 736.26, "end": 738.9, "duration": 2.6399999999999864, "section": "第2名｜兼職工讀生／打工族", "caption_text": "時薪再高，乘上不穩定的工時，總收入也搖搖欲墜。", "motion": "pan-right"}, {"scene_id": 183, "image_scene_id": 188, "start": 738.9, "end": 743.44, "duration": 4.540000000000077, "section": "第2名｜兼職工讀生／打工族", "caption_text": "一週排二十小時，一個月收入也就一萬六上下，", "motion": "slow-zoom-in"}, {"scene_id": 184, "image_scene_id": 189, "start": 743.44, "end": 747.64, "duration": 4.199999999999932, "section": "第2名｜兼職工讀生／打工族", "caption_text": "在都市裡，連一間雅房的房租都快付不起。", "motion": "slow-zoom-out"}, {"scene_id": 185, "image_scene_id": 190, "start": 747.64, "end": 752.37, "duration": 4.730000000000018, "section": "第2名｜兼職工讀生／打工族", "caption_text": "他們很多還是學生，要上課要考試還要賺生活費，", "motion": "pan-left"}, {"scene_id": 186, "image_scene_id": 191, "start": 752.37, "end": 757.15, "duration": 4.779999999999973, "section": "第2名｜兼職工讀生／打工族", "caption_text": "白天上課晚上補貨，燒掉的都是同一個年輕身體。", "motion": "pan-right"}, {"scene_id": 187, "image_scene_id": 192, "start": 757.15, "end": 761.83, "duration": 4.680000000000064, "section": "第2名｜兼職工讀生／打工族", "caption_text": "兼職沒有正式員工福利，收入完全無法預測，", "motion": "slow-zoom-in"}, {"scene_id": 188, "image_scene_id": 193, "start": 761.83, "end": 766.75, "duration": 4.919999999999959, "section": "第2名｜兼職工讀生／打工族", "caption_text": "有人領年薪百萬分紅，有人連下月班表都在等通知。", "motion": "slow-zoom-out"}, {"scene_id": 189, "image_scene_id": 194, "start": 766.75, "end": 769.44, "duration": 2.6900000000000546, "section": "第2名｜兼職工讀生／打工族", "caption_text": "他們撐起了服務業半壁江山，卻連生活費都要看班表臉色。", "motion": "pan-left"}, {"scene_id": 189, "image_scene_id": 195, "start": 769.44, "end": 772.13, "duration": 2.689999999999941, "section": "第2名｜兼職工讀生／打工族", "caption_text": "他們撐起了服務業半壁江山，卻連生活費都要看班表臉色。", "motion": "pan-right"}, {"scene_id": 190, "image_scene_id": 196, "start": 772.13, "end": 776.62, "duration": 4.490000000000009, "section": "第2名｜兼職工讀生／打工族", "caption_text": "系統從來沒有給過他們，一個能安穩努力的位置。", "motion": "slow-zoom-in"}, {"scene_id": 191, "image_scene_id": 197, "start": 776.62, "end": 781.11, "duration": 4.490000000000009, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "第一名，家庭看護與照顧服務基層工作者。", "motion": "slow-zoom-out"}, {"scene_id": 192, "image_scene_id": 198, "start": 781.11, "end": 785.84, "duration": 4.730000000000018, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "台灣正在高速老化，需要照顧的人一年比一年多。", "motion": "pan-left"}, {"scene_id": 193, "image_scene_id": 199, "start": 785.84, "end": 790.26, "duration": 4.419999999999959, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "照理說，照顧生命的工作應該是最被珍惜的，", "motion": "pan-right"}, {"scene_id": 194, "image_scene_id": 200, "start": 790.26, "end": 794.92, "duration": 4.659999999999968, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "但現實正好相反，他們是長照最底層的犧牲品。", "motion": "slow-zoom-in"}, {"scene_id": 195, "image_scene_id": 201, "start": 794.92, "end": 799.86, "duration": 4.940000000000055, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "幫長輩翻身、餵飯、洗澡、處理排泄物，", "motion": "slow-zoom-out"}, {"scene_id": 196, "image_scene_id": 202, "start": 799.86, "end": 804.4, "duration": 4.539999999999964, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "面對失智長輩的狂躁，還得把耐心當成日常。", "motion": "pan-left"}, {"scene_id": 197, "image_scene_id": 203, "start": 804.4, "end": 807.95, "duration": 3.550000000000068, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "手上托著的，不只是另一個人，", "motion": "pan-right"}, {"scene_id": 198, "image_scene_id": 204, "start": 807.95, "end": 810.61, "duration": 2.659999999999968, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "而是一個家庭的重量。", "motion": "slow-zoom-in"}, {"scene_id": 199, "image_scene_id": 205, "start": 810.61, "end": 815.58, "duration": 4.970000000000027, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "家庭看護更不存在下班這回事，二十四小時待命，", "motion": "slow-zoom-out"}, {"scene_id": 200, "image_scene_id": 206, "start": 815.58, "end": 818.87, "duration": 3.2899999999999636, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "工作和生活的界線徹底消失，", "motion": "pan-left"}, {"scene_id": 201, "image_scene_id": 207, "start": 818.87, "end": 823.05, "duration": 4.17999999999995, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "薪水折算成實際時薪，遠低於最低工資。", "motion": "pan-right"}, {"scene_id": 202, "image_scene_id": 208, "start": 823.05, "end": 827.01, "duration": 3.9600000000000364, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "價格受到家庭負擔力、政府補助、", "motion": "slow-zoom-in"}, {"scene_id": 203, "image_scene_id": 209, "start": 827.01, "end": 830.39, "duration": 3.3799999999999955, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "以及外籍看護行情等多重擠壓，", "motion": "slow-zoom-out"}, {"scene_id": 204, "image_scene_id": 210, "start": 830.39, "end": 834.61, "duration": 4.220000000000027, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "讓他們成為整個社福體系中最不被善待的一群。", "motion": "pan-left"}, {"scene_id": 205, "image_scene_id": 211, "start": 834.61, "end": 839.6, "duration": 4.990000000000009, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "同樣是照顧生命，醫護有制度保障、有職涯階梯，", "motion": "pan-right"}, {"scene_id": 206, "image_scene_id": 212, "start": 839.6, "end": 843.15, "duration": 3.5499999999999545, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "基層照服員卻常常孤立無援，", "motion": "slow-zoom-in"}, {"scene_id": 207, "image_scene_id": 213, "start": 843.15, "end": 846.7, "duration": 3.550000000000068, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "撐起台灣正在崩塌的長照現場。", "motion": "slow-zoom-out"}, {"scene_id": 208, "image_scene_id": 214, "start": 846.7, "end": 850.71, "duration": 4.009999999999991, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "這份工作做得越好，越代表社會需要他，", "motion": "pan-left"}, {"scene_id": 209, "image_scene_id": 215, "start": 850.71, "end": 854.31, "duration": 3.599999999999909, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "但越需要他，卻越得不到對等的回報。", "motion": "pan-right"}, {"scene_id": 210, "image_scene_id": 216, "start": 854.31, "end": 858.44, "duration": 4.130000000000109, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "這不只是薪資問題，更是台灣整個社會，", "motion": "slow-zoom-in"}, {"scene_id": 211, "image_scene_id": 217, "start": 858.44, "end": 861.75, "duration": 3.3099999999999454, "section": "第1名｜家庭看護／照顧服務基層工作者", "caption_text": "遲早要正面回答的生存難題。", "motion": "slow-zoom-out"}, {"scene_id": 212, "image_scene_id": 218, "start": 861.75, "end": 865.59, "duration": 3.840000000000032, "section": "結尾與呼籲行動", "caption_text": "這十種職業，並不是少數人的特例，", "motion": "pan-left"}, {"scene_id": 213, "image_scene_id": 219, "start": 865.59, "end": 869.74, "duration": 4.149999999999977, "section": "結尾與呼籲行動", "caption_text": "而是一整個世代在台灣結構下的集體處境。", "motion": "pan-right"}, {"scene_id": 214, "image_scene_id": 220, "start": 869.74, "end": 873.24, "duration": 3.5, "section": "結尾與呼籲行動", "caption_text": "低薪從來不是不努力的個人問題，", "motion": "slow-zoom-in"}, {"scene_id": 215, "image_scene_id": 221, "start": 873.24, "end": 876.86, "duration": 3.6200000000000045, "section": "結尾與呼籲行動", "caption_text": "而是整個社會系統運作下的必然產物。", "motion": "slow-zoom-out"}, {"scene_id": 216, "image_scene_id": 222, "start": 876.86, "end": 880.29, "duration": 3.42999999999995, "section": "結尾與呼籲行動", "caption_text": "他們用雙手、淚水與情緒，", "motion": "pan-left"}, {"scene_id": 217, "image_scene_id": 223, "start": 880.29, "end": 883.77, "duration": 3.480000000000018, "section": "結尾與呼籲行動", "caption_text": "撐起了這座城市的便利與安穩，", "motion": "pan-right"}, {"scene_id": 218, "image_scene_id": 224, "start": 883.77, "end": 887.51, "duration": 3.740000000000009, "section": "結尾與呼籲行動", "caption_text": "社會不該轉過頭去、視若無睹。", "motion": "slow-zoom-in"}, {"scene_id": 219, "image_scene_id": 225, "start": 887.51, "end": 892.14, "duration": 4.6299999999999955, "section": "結尾與呼籲行動", "caption_text": "今天介紹的這十個職業中，哪一個最讓你感同身受？", "motion": "slow-zoom-out"}, {"scene_id": 220, "image_scene_id": 226, "start": 892.14, "end": 896.2, "duration": 4.060000000000059, "section": "結尾與呼籲行動", "caption_text": "歡迎在底下留言，告訴我們你的故事。", "motion": "pan-left"}, {"scene_id": 221, "image_scene_id": 227, "start": 896.2, "end": 900.54, "duration": 4.339999999999918, "section": "結尾與呼籲行動", "caption_text": "希望更多人看見台灣底層勞工的真實處境，", "motion": "pan-right"}, {"scene_id": 222, "image_scene_id": 228, "start": 900.54, "end": 904.26, "duration": 3.7200000000000273, "section": "結尾與呼籲行動", "caption_text": "請幫我們點讚、訂閱好奇風向標，", "motion": "slow-zoom-in"}, {"scene_id": 223, "image_scene_id": 229, "start": 904.26, "end": 907.4, "duration": 3.1399999999999864, "section": "結尾與呼籲行動", "caption_text": "並將影片分享給你的朋友。", "motion": "slow-zoom-out"}, {"scene_id": 224, "image_scene_id": 230, "start": 907.4, "end": 909.54, "duration": 2.1399999999999864, "section": "結尾與呼籲行動", "caption_text": "我們下期見。", "motion": "pan-left"}], "captions": [{"id": 1, "start": 0.0, "end": 3.6, "text": "一個月到手不到三萬二，在臺灣，", "section": "開場 Hook"}, {"id": 2, "start": 3.6, "end": 6.91, "text": "究竟是一份工作的真實行情，", "section": "開場 Hook"}, {"id": 3, "start": 6.91, "end": 10.65, "text": "還是一道被整個社會刻意繞開的警訊？", "section": "開場 Hook"}, {"id": 4, "start": 10.65, "end": 14.25, "text": "先別急著把低薪推給年輕人不努力，", "section": "開場 Hook"}, {"id": 5, "start": 14.25, "end": 18.35, "text": "當數據一旦攤開，真相遠比不努力更殘酷。", "section": "開場 Hook"}, {"id": 6, "start": 18.35, "end": 21.9, "text": "二零二零年開始臺灣的最低工資，", "section": "開場 Hook"}, {"id": 7, "start": 21.9, "end": 25.67, "text": "已經調高到月薪兩萬九千五百元，", "section": "開場 Hook"}, {"id": 8, "start": 25.67, "end": 29.25, "text": "這聽起來一切都在朝對的方向走，", "section": "開場 Hook"}, {"id": 9, "start": 29.25, "end": 33.16, "text": "但把鏡頭拉近會看見另一組扎心數字。", "section": "開場 Hook"}, {"id": 10, "start": 33.16, "end": 36.9, "text": "全台受雇員工全年總薪資中位數，", "section": "開場 Hook"}, {"id": 11, "start": 36.9, "end": 39.73, "text": "是五十四萬六千元，", "section": "開場 Hook"}, {"id": 12, "start": 39.73, "end": 43.23, "text": "而低薪產業全年總薪資中位數，", "section": "開場 Hook"}, {"id": 13, "start": 43.23, "end": 46.09, "text": "卻只有三十八萬上下。", "section": "開場 Hook"}, {"id": 14, "start": 46.09, "end": 49.71, "text": "這十六萬多的落差不是抽象的統計，", "section": "開場 Hook"}, {"id": 15, "start": 49.71, "end": 53.21, "text": "而是每個月一萬三千多元的差距，", "section": "開場 Hook"}, {"id": 16, "start": 53.21, "end": 57.1, "text": "是決定能不能交出房租學費的分水嶺。", "section": "開場 Hook"}, {"id": 17, "start": 57.1, "end": 60.17, "text": "今天就跟著好奇風向標，", "section": "開場 Hook"}, {"id": 18, "start": 60.17, "end": 63.77, "text": "一起看看台灣薪資最低的十種職業。", "section": "開場 Hook"}, {"id": 19, "start": 63.77, "end": 67.78, "text": "第十名，行政助理與一般文書人員。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 20, "start": 67.78, "end": 72.12, "text": "這大概是所有職缺裡最被當成理所當然的。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 21, "start": 72.12, "end": 76.08, "text": "表面上他是坐在辦公室吹冷氣的白領，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 22, "start": 76.08, "end": 79.15, "text": "名片上硬著專員兩個字，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 23, "start": 79.15, "end": 83.4, "text": "實際上他是一間公司裡最安靜也最忙的雜工。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 24, "start": 83.4, "end": 87.22, "text": "阿的一天從計算機開機那一刻就失控了，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 25, "start": 87.22, "end": 91.37, "text": "電話永遠比人先到，一杯水還沒喝完，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 26, "start": 91.37, "end": 94.49, "text": "下一個指令就又壓了下來，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 27, "start": 94.49, "end": 98.74, "text": "收發信件、整理資料、甚至倒水，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 28, "start": 98.74, "end": 103.13, "text": "還有打掃廁所，最後全落到同一個人頭上。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 29, "start": 103.13, "end": 106.75, "text": "行政助理在中小企業更像一塊磚，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 30, "start": 106.75, "end": 110.83, "text": "哪裡缺就往哪裡搬，身兼多重角色，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 31, "start": 110.83, "end": 114.72, "text": "替代性極高，也代表隨時可以被替換。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 32, "start": 114.72, "end": 118.73, "text": "更關鍵的是，行政不屬於賺錢的部門，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 33, "start": 118.73, "end": 122.93, "text": "不經手合約，業績表上永遠沒有他的名字，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 34, "start": 122.93, "end": 127.06, "text": "所以薪資表上的數字，永遠靜止不動。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 35, "start": 127.06, "end": 131.21, "text": "隔壁業務成交一筆獎金可能超過他整個月，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 36, "start": 131.21, "end": 135.05, "text": "而行政助理把整間公司的雜事吞下，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 37, "start": 135.05, "end": 138.58, "text": "卻連一句辛苦了，都很少換來。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 38, "start": 138.58, "end": 142.88, "text": "行政助理排在第十名，不是工作沒價值，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 39, "start": 142.88, "end": 147.01, "text": "而是市場太習慣他的存在，習慣到忘了，", "section": "第10名｜行政助理／一般文書人員"}, {"id": 40, "start": 147.01, "end": 151.07, "text": "整間公司的運轉，其實都靠他一個人在撐。", "section": "第10名｜行政助理／一般文書人員"}, {"id": 41, "start": 151.07, "end": 154.77, "text": "你身邊，是不是也有這樣的一個人？", "section": "第10名｜行政助理／一般文書人員"}, {"id": 42, "start": 154.77, "end": 158.92, "text": "第九名，門市人員與賣場銷售人員。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 43, "start": 158.92, "end": 161.94, "text": "他們撐起了整條街的燈火，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 44, "start": 161.94, "end": 165.64, "text": "卻很少被進店的顧客正眼看過一次。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 45, "start": 165.64, "end": 169.74, "text": "很多人以為門市工作就是站在店裡等客人，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 46, "start": 169.74, "end": 173.96, "text": "錯了，真正的一天，從開店前就開始了。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 47, "start": 173.96, "end": 178.09, "text": "補貨搬到腰酸，衣服一件件摺好上架，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 48, "start": 178.09, "end": 182.1, "text": "標價錢一張張重貼，還要盤點到半夜，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 49, "start": 182.1, "end": 186.08, "text": "數字對不上，就整層從頭再來一次。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 50, "start": 186.08, "end": 190.06, "text": "光是站著，就是一種巨大的體力消耗，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 51, "start": 190.06, "end": 194.24, "text": "每天站立八到十小時，小腿和膝蓋，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 52, "start": 194.24, "end": 197.79, "text": "替這份薪水付出了最慘痛的代價。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 53, "start": 197.79, "end": 201.82, "text": "遇到大檔期進貨量翻倍，搬貨到手軟，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 54, "start": 201.82, "end": 205.97, "text": "連坐下來喘口氣，都成了奢侈的幻想。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 55, "start": 205.97, "end": 209.81, "text": "好不容易熬到打烊，還要截帳清點，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 56, "start": 209.81, "end": 213.65, "text": "底薪很低，剩下的全看業績抽成。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 57, "start": 213.65, "end": 217.75, "text": "問題是商圈人潮會退，電商也會搶單，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 58, "start": 217.75, "end": 221.9, "text": "業績掉，抽成沒了，但人還是要站，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 59, "start": 221.9, "end": 226.32, "text": "抽成說穿了，是把經營風險轉嫁給第一線。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 60, "start": 226.32, "end": 230.71, "text": "他們九站、輪班、假日全部都在工作，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 61, "start": 230.71, "end": 235.01, "text": "薪資卻長期卡在比最低工資高一點點的位置。", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 62, "start": 235.01, "end": 238.87, "text": "當你下次逛街覺得這家店服務很好的時候，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 63, "start": 238.87, "end": 243.17, "text": "有沒有想過，那個人是站了整整八個小時，", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 64, "start": 243.17, "end": 245.95, "text": "才換來你這一秒的滿意？", "section": "第9名｜門市人員／賣場銷售人員"}, {"id": 65, "start": 245.95, "end": 249.14, "text": "第八名，電話客服人員。", "section": "第8名｜電話客服人員"}, {"id": 66, "start": 249.14, "end": 253.34, "text": "這是一份看不見臉，卻要逼自己笑的工作。", "section": "第8名｜電話客服人員"}, {"id": 67, "start": 253.34, "end": 257.56, "text": "耳機戴上，八個小時裡耳邊只有負面情緒，", "section": "第8名｜電話客服人員"}, {"id": 68, "start": 257.56, "end": 262.31, "text": "催貨的、退款的、乃至純粹找人出氣的，", "section": "第8名｜電話客服人員"}, {"id": 69, "start": 262.31, "end": 266.44, "text": "電話一接起來，第一句話往往是指責。", "section": "第8名｜電話客服人員"}, {"id": 70, "start": 266.44, "end": 270.95, "text": "客服人員必須在標準流程裡，把委屈吞下去，", "section": "第8名｜電話客服人員"}, {"id": 71, "start": 270.95, "end": 275.39, "text": "不能頂嘴、不能掛斷、不能顯露任何不滿，", "section": "第8名｜電話客服人員"}, {"id": 72, "start": 275.39, "end": 279.42, "text": "因為每一通電話都有錄音，每句都有評分。", "section": "第8名｜電話客服人員"}, {"id": 73, "start": 279.42, "end": 283.98, "text": "下了班才發現，自己一直在演情緒穩定的人，", "section": "第8名｜電話客服人員"}, {"id": 74, "start": 283.98, "end": 288.3, "text": "時間久了，連自己真正的情緒都分不清楚了。", "section": "第8名｜電話客服人員"}, {"id": 75, "start": 288.3, "end": 290.965, "text": "為什麽這麽累薪水卻低？因為企業視為成本，", "section": "第8名｜電話客服人員"}, {"id": 76, "start": 290.965, "end": 293.63, "text": "為什麽這麽累薪水卻低？因為企業視為成本，", "section": "第8名｜電話客服人員"}, {"id": 77, "start": 293.63, "end": 297.97, "text": "做得好是應該，但只要一通投訴就前功盡棄。", "section": "第8名｜電話客服人員"}, {"id": 78, "start": 297.97, "end": 301.4, "text": "底薪往往就落在最低工資附近，", "section": "第8名｜電話客服人員"}, {"id": 79, "start": 301.4, "end": 305.94, "text": "那些加班費加一家，才勉強看起來像份薪水。", "section": "第8名｜電話客服人員"}, {"id": 80, "start": 305.94, "end": 310.62, "text": "情緒勞動，是這份工作最累也最隱形的成本。", "section": "第8名｜電話客服人員"}, {"id": 81, "start": 310.62, "end": 314.46, "text": "電話客服守護了品牌最後的一道門面，", "section": "第8名｜電話客服人員"}, {"id": 82, "start": 314.46, "end": 318.76, "text": "卻很少有人回頭問一句，那個人過得好不好？", "section": "第8名｜電話客服人員"}, {"id": 83, "start": 318.76, "end": 322.94, "text": "下一次你想對客服發脾氣時，請記得，", "section": "第8名｜電話客服人員"}, {"id": 84, "start": 322.94, "end": 326.83, "text": "電話那一頭也是同樣在為生活努力的人。", "section": "第8名｜電話客服人員"}, {"id": 85, "start": 326.83, "end": 330.84, "text": "第七名，安親班老師與補習班助教。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 86, "start": 330.84, "end": 335.42, "text": "聽到教育兩個字，腦海裡浮現的是講台光環，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 87, "start": 335.42, "end": 340.1, "text": "但真正撐起補教產業的，卻是那些光照不到的人。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 88, "start": 340.1, "end": 344.16, "text": "安親班老師的一天，從放學的鐘聲開始，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 89, "start": 344.16, "end": 348.02, "text": "要站在校門口接孩子，一個都不能少。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 90, "start": 348.02, "end": 350.54, "text": "回到教室，改作業、盯功課、複習進度，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 91, "start": 350.54, "end": 353.06, "text": "回到教室，改作業、盯功課、複習進度，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 92, "start": 353.06, "end": 357.33, "text": "聯絡簿一本本回，家長的訊息深夜還在響，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 93, "start": 357.33, "end": 360.59, "text": "字裡行間全都是焦慮和責怪。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 94, "start": 360.59, "end": 364.53, "text": "孩子跌倒要處理，孩子吵架要排解，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 95, "start": 364.53, "end": 368.44, "text": "考砸了，第一個被追著問的還是老師。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 96, "start": 368.44, "end": 373.07, "text": "這份工作有個殘酷特質：責任大得像養孩子，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 97, "start": 373.07, "end": 376.26, "text": "回報卻小得像在領零用錢。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 98, "start": 376.26, "end": 380.41, "text": "一個老師要同時面對十幾個學生和家庭，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 99, "start": 380.41, "end": 384.63, "text": "稍有疏忽，就是隔天家長一早的投訴電話。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 100, "start": 384.63, "end": 389.29, "text": "責任全天候掛身上，薪水卻沒跟著責任算。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 101, "start": 389.29, "end": 393.73, "text": "市場競爭激烈，小型補習班為了活下去，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 102, "start": 393.73, "end": 398.07, "text": "基層助教和課照老師就成了最先被壓縮的。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 103, "start": 398.07, "end": 402.32, "text": "改不完的作業，加上招生季還要發傳單，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 104, "start": 402.32, "end": 406.86, "text": "明星名師一堂課的收入，可能超過他一整月。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 105, "start": 406.86, "end": 411.25, "text": "他們用愛心撐起孩子，卻換不來體面的未來。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 106, "start": 411.25, "end": 414.73, "text": "這份工作，抗著別人的未來，", "section": "第7名｜安親班老師／補習班助教"}, {"id": 107, "start": 414.73, "end": 417.47, "text": "卻養不起自己的現在。", "section": "第7名｜安親班老師／補習班助教"}, {"id": 108, "start": 417.47, "end": 421.55, "text": "第六名，清潔人員與環境整理人員。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 109, "start": 421.55, "end": 425.53, "text": "凌晨四點，大多數人還在溫暖的夢鄉，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 110, "start": 425.53, "end": 429.95, "text": "清潔人員已經穿上反光背心，開始工作。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 111, "start": 429.95, "end": 434.22, "text": "他們是城市裡最早上班卻最不被看見的一群。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 112, "start": 434.22, "end": 438.73, "text": "辦公室垃圾桶、醫院消毒水、捷運月台，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 113, "start": 438.73, "end": 443.19, "text": "每一處乾淨背後，都站著一雙磨出老繭的手。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 114, "start": 443.19, "end": 447.61, "text": "他們在人群醒來前工作，在散去之後收尾，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 115, "start": 447.61, "end": 452.03, "text": "永遠站在最不起眼的角落，做不能中斷的事。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 116, "start": 452.03, "end": 456.37, "text": "只要停工一天，整棟大樓就會陷入癱瘓惡臭。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 117, "start": 456.37, "end": 460.21, "text": "這份工作的專業，長期被嚴重低估，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 118, "start": 460.21, "end": 465.03, "text": "醫院感控消毒、無塵室落塵控制，都需技術。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 119, "start": 465.03, "end": 469.21, "text": "但這份專業，卻從來沒有反映在薪水上。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 120, "start": 469.21, "end": 473.99, "text": "更關鍵的是外包制度橫行，中間商層層剝水，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 121, "start": 473.99, "end": 478.5, "text": "最後進到口袋的薪水，已經被壓得所剩無幾。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 122, "start": 478.5, "end": 482.96, "text": "用最耗體力的方式，換來最接近最低的數字。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 123, "start": 482.96, "end": 487.66, "text": "做了十幾年清潔，薪水也只勉強跟著低薪調。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 124, "start": 487.66, "end": 492.08, "text": "我們習慣了乾淨，卻習慣忽視擦地板的背影。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 125, "start": 492.08, "end": 496.42, "text": "下次再看見彎著腰的人，請給予應有的尊重，", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 126, "start": 496.42, "end": 500.07, "text": "那個背影，值得被整個社會看見。", "section": "第6名｜清潔人員／環境整理人員"}, {"id": 127, "start": 500.07, "end": 503.62, "text": "第五名，餐飲外場服務人員。", "section": "第5名｜餐飲外場服務人員"}, {"id": 128, "start": 503.62, "end": 507.84, "text": "餐廳的尖峰時段，是一場沒有硝煙的戰爭。", "section": "第5名｜餐飲外場服務人員"}, {"id": 129, "start": 507.84, "end": 512.11, "text": "中午十二點到一點，點單像雪片一樣飛來，", "section": "第5名｜餐飲外場服務人員"}, {"id": 130, "start": 512.11, "end": 516.55, "text": "外場人員一手端著托盤，腦子裡默默記桌號，", "section": "第5名｜餐飲外場服務人員"}, {"id": 131, "start": 516.55, "end": 521.13, "text": "腳下幾乎是跑步的節奏，送餐收桌補餐具，", "section": "第5名｜餐飲外場服務人員"}, {"id": 132, "start": 521.13, "end": 525.38, "text": "还要應付催菜的客人，安撫暴躁的情緒。", "section": "第5名｜餐飲外場服務人員"}, {"id": 133, "start": 525.38, "end": 530.11, "text": "汗水是工作最固定的配件，水擺在角落放涼，", "section": "第5名｜餐飲外場服務人員"}, {"id": 134, "start": 530.11, "end": 533.83, "text": "常常找不到一個空檔，喝上一口。", "section": "第5名｜餐飲外場服務人員"}, {"id": 135, "start": 533.83, "end": 538.17, "text": "下班的時候小腿腫了一圈，腳痛得像踩針尖。", "section": "第5名｜餐飲外場服務人員"}, {"id": 136, "start": 538.17, "end": 542.35, "text": "用餐時段一過，還要擦桌拖地恢復戰場，", "section": "第5名｜餐飲外場服務人員"}, {"id": 137, "start": 542.35, "end": 546.72, "text": "而這一切，換來的薪水卻少得令人心寒。", "section": "第5名｜餐飲外場服務人員"}, {"id": 138, "start": 546.72, "end": 550.99, "text": "基層餐飲的薪水，很多還是用時薪計算，", "section": "第5名｜餐飲外場服務人員"}, {"id": 139, "start": 550.99, "end": 555.38, "text": "一旦排班時數被砍，實領甚至養不起自己。", "section": "第5名｜餐飲外場服務人員"}, {"id": 140, "start": 555.38, "end": 559.72, "text": "年年喊缺工，卻不願意把薪水真正往上提升，", "section": "第5名｜餐飲外場服務人員"}, {"id": 141, "start": 559.72, "end": 563.75, "text": "這是台灣服務業常年累積下來的結構困境。", "section": "第5名｜餐飲外場服務人員"}, {"id": 142, "start": 563.75, "end": 568.19, "text": "送上的每道菜都燙手，卻燙不出像樣的薪水；", "section": "第5名｜餐飲外場服務人員"}, {"id": 143, "start": 568.19, "end": 571.81, "text": "每分鐘的勞動都算得清清楚楚，", "section": "第5名｜餐飲外場服務人員"}, {"id": 144, "start": 571.81, "end": 575.1, "text": "卻唯獨算不出一個像樣的未來。", "section": "第5名｜餐飲外場服務人員"}, {"id": 145, "start": 575.1, "end": 578.29, "text": "第四名，住宿房務人員。", "section": "第4名｜住宿房務人員"}, {"id": 146, "start": 578.29, "end": 581.94, "text": "在飯店裡，最體面的永遠是大廳，", "section": "第4名｜住宿房務人員"}, {"id": 147, "start": 581.94, "end": 584.8, "text": "最血汗的永遠是後場。", "section": "第4名｜住宿房務人員"}, {"id": 148, "start": 584.8, "end": 589.19, "text": "退房的客人一走，房務就要開始和時間賽跑，", "section": "第4名｜住宿房務人員"}, {"id": 149, "start": 589.19, "end": 593.73, "text": "一間房十幾分鐘，床單要抖平，浴室要擦乾，", "section": "第4名｜住宿房務人員"}, {"id": 150, "start": 593.73, "end": 598.17, "text": "每一個細節，都會被下一位客人的眼睛放大。", "section": "第4名｜住宿房務人員"}, {"id": 151, "start": 598.17, "end": 600.88, "text": "彎腰、蹲下、抬手，同樣動作一天重複上百次，", "section": "第4名｜住宿房務人員"}, {"id": 152, "start": 600.88, "end": 603.59, "text": "彎腰、蹲下、抬手，同樣動作一天重複上百次，", "section": "第4名｜住宿房務人員"}, {"id": 153, "start": 603.59, "end": 607.93, "text": "腰背和手腕，是這份工作最早暴廢的部位。", "section": "第4名｜住宿房務人員"}, {"id": 154, "start": 607.93, "end": 612.25, "text": "遇到狂歡後的混亂房間，工作量直接翻倍，", "section": "第4名｜住宿房務人員"}, {"id": 155, "start": 612.25, "end": 615.73, "text": "但薪水，絕對不會跟著翻倍。", "section": "第4名｜住宿房務人員"}, {"id": 156, "start": 615.73, "end": 619.02, "text": "旅客享受一晚數千元的房間，", "section": "第4名｜住宿房務人員"}, {"id": 157, "start": 619.02, "end": 623.22, "text": "房務領的，卻是一間房不到百元的清潔費。", "section": "第4名｜住宿房務人員"}, {"id": 158, "start": 623.22, "end": 627.92, "text": "營運成本高，人力又常外包，薪水常年被壓死。", "section": "第4名｜住宿房務人員"}, {"id": 159, "start": 627.92, "end": 631.81, "text": "他們用最快的速度替別人鋪好乾淨的床，", "section": "第4名｜住宿房務人員"}, {"id": 160, "start": 631.81, "end": 635.19, "text": "卻鋪不出自己一張穩定的薪水單。", "section": "第4名｜住宿房務人員"}, {"id": 161, "start": 635.19, "end": 638.36, "text": "第三名，美容美髮助理。", "section": "第3名｜美容美髮助理"}, {"id": 162, "start": 638.36, "end": 641.82, "text": "這是年輕人踏進服務業的第一站，", "section": "第3名｜美容美髮助理"}, {"id": 163, "start": 641.82, "end": 645.44, "text": "也是用夢想換薪水最典型的一站。", "section": "第3名｜美容美髮助理"}, {"id": 164, "start": 645.44, "end": 647.97, "text": "洗頭、沖水、收拾染膏藥水、清掃碎髮，", "section": "第3名｜美容美髮助理"}, {"id": 165, "start": 647.97, "end": 650.5, "text": "洗頭、沖水、收拾染膏藥水、清掃碎髮，", "section": "第3名｜美容美髮助理"}, {"id": 166, "start": 650.5, "end": 655.11, "text": "手泡在洗髮精裡一整天，指縫乾裂直接脫皮，", "section": "第3名｜美容美髮助理"}, {"id": 167, "start": 655.11, "end": 658.49, "text": "這是刻在每一雙手上的職業傷害。", "section": "第3名｜美容美髮助理"}, {"id": 168, "start": 658.49, "end": 662.79, "text": "最殘酷的是學徒兩個字，掛上學徒名義，", "section": "第3名｜美容美髮助理"}, {"id": 169, "start": 662.79, "end": 665.93, "text": "薪水就被理所當然地壓低，", "section": "第3名｜美容美髮助理"}, {"id": 170, "start": 665.93, "end": 670.71, "text": "要學技術，還得靠下班後的無酬時間自己練習。", "section": "第3名｜美容美髮助理"}, {"id": 171, "start": 670.71, "end": 675.29, "text": "行業收入兩個極端，熬出頭的設計師越入十萬，", "section": "第3名｜美容美髮助理"}, {"id": 172, "start": 675.29, "end": 679.63, "text": "但助理全年總薪資中位數卻只有三十八萬一千，", "section": "第3名｜美容美髮助理"}, {"id": 173, "start": 679.63, "end": 683.97, "text": "很多人在助理階段，就被低薪磨掉了熱情。", "section": "第3名｜美容美髮助理"}, {"id": 174, "start": 683.97, "end": 687.28, "text": "設計師在鏡子前收穫掌聲，", "section": "第3名｜美容美髮助理"}, {"id": 175, "start": 687.28, "end": 691.65, "text": "助理只能整天泡在水裡，換來薄薄的薪水單。", "section": "第3名｜美容美髮助理"}, {"id": 176, "start": 691.65, "end": 695.87, "text": "通往未來的路，要人用漫長的青春去墊底，", "section": "第3名｜美容美髮助理"}, {"id": 177, "start": 695.87, "end": 700.26, "text": "而這份墊底的青春，很多人根本熬不到出頭。", "section": "第3名｜美容美髮助理"}, {"id": 178, "start": 700.26, "end": 704.05, "text": "第二名，兼職工讀生與打工族。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 179, "start": 704.05, "end": 708.63, "text": "嚴格來說這不是一個職業，而是一種集體處境。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 180, "start": 708.63, "end": 713.48, "text": "最低時薪調高到一百九十六元，看起來在進步，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 181, "start": 713.48, "end": 717.94, "text": "但真正綁住打工族的，從來不是時薪這兩個字，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 182, "start": 717.94, "end": 720.58, "text": "而是排班這一張紙。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 183, "start": 720.58, "end": 724.64, "text": "老闆為了控制成本，班表永遠在浮動，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 184, "start": 724.64, "end": 729.01, "text": "這週排二十小時，下週可能只剩八小時。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 185, "start": 729.01, "end": 733.62, "text": "多排一班是運氣，少排一班就是房租的缺口。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 186, "start": 733.62, "end": 736.26, "text": "時薪再高，乘上不穩定的工時，總收入也搖搖欲墜。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 187, "start": 736.26, "end": 738.9, "text": "時薪再高，乘上不穩定的工時，總收入也搖搖欲墜。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 188, "start": 738.9, "end": 743.44, "text": "一週排二十小時，一個月收入也就一萬六上下，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 189, "start": 743.44, "end": 747.64, "text": "在都市裡，連一間雅房的房租都快付不起。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 190, "start": 747.64, "end": 752.37, "text": "他們很多還是學生，要上課要考試還要賺生活費，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 191, "start": 752.37, "end": 757.15, "text": "白天上課晚上補貨，燒掉的都是同一個年輕身體。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 192, "start": 757.15, "end": 761.83, "text": "兼職沒有正式員工福利，收入完全無法預測，", "section": "第2名｜兼職工讀生／打工族"}, {"id": 193, "start": 761.83, "end": 766.75, "text": "有人領年薪百萬分紅，有人連下月班表都在等通知。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 194, "start": 766.75, "end": 769.44, "text": "他們撐起了服務業半壁江山，卻連生活費都要看班表臉色。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 195, "start": 769.44, "end": 772.13, "text": "他們撐起了服務業半壁江山，卻連生活費都要看班表臉色。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 196, "start": 772.13, "end": 776.62, "text": "系統從來沒有給過他們，一個能安穩努力的位置。", "section": "第2名｜兼職工讀生／打工族"}, {"id": 197, "start": 776.62, "end": 781.11, "text": "第一名，家庭看護與照顧服務基層工作者。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 198, "start": 781.11, "end": 785.84, "text": "台灣正在高速老化，需要照顧的人一年比一年多。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 199, "start": 785.84, "end": 790.26, "text": "照理說，照顧生命的工作應該是最被珍惜的，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 200, "start": 790.26, "end": 794.92, "text": "但現實正好相反，他們是長照最底層的犧牲品。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 201, "start": 794.92, "end": 799.86, "text": "幫長輩翻身、餵飯、洗澡、處理排泄物，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 202, "start": 799.86, "end": 804.4, "text": "面對失智長輩的狂躁，還得把耐心當成日常。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 203, "start": 804.4, "end": 807.95, "text": "手上托著的，不只是另一個人，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 204, "start": 807.95, "end": 810.61, "text": "而是一個家庭的重量。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 205, "start": 810.61, "end": 815.58, "text": "家庭看護更不存在下班這回事，二十四小時待命，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 206, "start": 815.58, "end": 818.87, "text": "工作和生活的界線徹底消失，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 207, "start": 818.87, "end": 823.05, "text": "薪水折算成實際時薪，遠低於最低工資。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 208, "start": 823.05, "end": 827.01, "text": "價格受到家庭負擔力、政府補助、", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 209, "start": 827.01, "end": 830.39, "text": "以及外籍看護行情等多重擠壓，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 210, "start": 830.39, "end": 834.61, "text": "讓他們成為整個社福體系中最不被善待的一群。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 211, "start": 834.61, "end": 839.6, "text": "同樣是照顧生命，醫護有制度保障、有職涯階梯，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 212, "start": 839.6, "end": 843.15, "text": "基層照服員卻常常孤立無援，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 213, "start": 843.15, "end": 846.7, "text": "撐起台灣正在崩塌的長照現場。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 214, "start": 846.7, "end": 850.71, "text": "這份工作做得越好，越代表社會需要他，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 215, "start": 850.71, "end": 854.31, "text": "但越需要他，卻越得不到對等的回報。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 216, "start": 854.31, "end": 858.44, "text": "這不只是薪資問題，更是台灣整個社會，", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 217, "start": 858.44, "end": 861.75, "text": "遲早要正面回答的生存難題。", "section": "第1名｜家庭看護／照顧服務基層工作者"}, {"id": 218, "start": 861.75, "end": 865.59, "text": "這十種職業，並不是少數人的特例，", "section": "結尾與呼籲行動"}, {"id": 219, "start": 865.59, "end": 869.74, "text": "而是一整個世代在台灣結構下的集體處境。", "section": "結尾與呼籲行動"}, {"id": 220, "start": 869.74, "end": 873.24, "text": "低薪從來不是不努力的個人問題，", "section": "結尾與呼籲行動"}, {"id": 221, "start": 873.24, "end": 876.86, "text": "而是整個社會系統運作下的必然產物。", "section": "結尾與呼籲行動"}, {"id": 222, "start": 876.86, "end": 880.29, "text": "他們用雙手、淚水與情緒，", "section": "結尾與呼籲行動"}, {"id": 223, "start": 880.29, "end": 883.77, "text": "撐起了這座城市的便利與安穩，", "section": "結尾與呼籲行動"}, {"id": 224, "start": 883.77, "end": 887.51, "text": "社會不該轉過頭去、視若無睹。", "section": "結尾與呼籲行動"}, {"id": 225, "start": 887.51, "end": 892.14, "text": "今天介紹的這十個職業中，哪一個最讓你感同身受？", "section": "結尾與呼籲行動"}, {"id": 226, "start": 892.14, "end": 896.2, "text": "歡迎在底下留言，告訴我們你的故事。", "section": "結尾與呼籲行動"}, {"id": 227, "start": 896.2, "end": 900.54, "text": "希望更多人看見台灣底層勞工的真實處境，", "section": "結尾與呼籲行動"}, {"id": 228, "start": 900.54, "end": 904.26, "text": "請幫我們點讚、訂閱好奇風向標，", "section": "結尾與呼籲行動"}, {"id": 229, "start": 904.26, "end": 907.4, "text": "並將影片分享給你的朋友。", "section": "結尾與呼籲行動"}, {"id": 230, "start": 907.4, "end": 909.54, "text": "我們下期見。", "section": "結尾與呼籲行動"}]};
